definition:
CREATE OR REPLACE FUNCTION private.can_delete_task(target_task_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.tasks as task
    where task.id = target_task_id
      and (
        private.has_permission(
          task.organization_id,
          'tasks.delete_all'
        )

        or (
          private.has_permission(
            task.organization_id,
            'tasks.delete_own'
          )

          and (
            task.assigned_to = (select auth.uid())
            or task.created_by = (select auth.uid())
          )
        )
      )
  );
$function$

CREATE OR REPLACE FUNCTION private.can_edit_lead(target_lead_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.leads as lead

    where lead.id = target_lead_id

      and private.can_operate_pipeline_stage(
        lead.stage_id
      )

      and (
        private.has_permission(
          lead.organization_id,
          'leads.update_all'
        )

        or (
          private.has_permission(
            lead.organization_id,
            'leads.update_assigned'
          )

          and (
            private.is_current_user_linked_to_lead(
              lead.id,
              true
            )

            or (
              lead.assigned_to is null

              and private.has_permission(
                lead.organization_id,
                'leads.read_unassigned'
              )
            )
          )
        )
      )
  );
$function$

CREATE OR REPLACE FUNCTION private.can_edit_task(target_task_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.tasks as task
    where task.id = target_task_id
      and (
        private.has_permission(
          task.organization_id,
          'tasks.update_all'
        )

        or (
          private.has_permission(
            task.organization_id,
            'tasks.update_own'
          )

          and (
            task.assigned_to = (select auth.uid())
            or task.created_by = (select auth.uid())
          )
        )
      )
  );
$function$

CREATE OR REPLACE FUNCTION private.can_view_lead(target_lead_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.leads as lead

    where lead.id = target_lead_id

      and private.can_view_pipeline_stage(
        lead.stage_id
      )

      and (
        private.has_permission(
          lead.organization_id,
          'leads.read_all'
        )

        or (
          private.has_permission(
            lead.organization_id,
            'leads.read_assigned'
          )

          and private.is_current_user_linked_to_lead(
            lead.id,
            false
          )
        )

        or (
          lead.assigned_to is null

          and private.has_permission(
            lead.organization_id,
            'leads.read_unassigned'
          )
        )
      )
  );
$function$

CREATE OR REPLACE FUNCTION private.can_view_task(target_task_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.tasks as task
    where task.id = target_task_id
      and (
        private.has_permission(
          task.organization_id,
          'tasks.read_all'
        )

        or (
          private.has_permission(
            task.organization_id,
            'tasks.read_own'
          )

          and (
            task.assigned_to = (select auth.uid())
            or task.created_by = (select auth.uid())
          )
        )
      )
  );
$function$

CREATE OR REPLACE FUNCTION private.hydrate_message_media_from_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  media jsonb;
begin
  if new.message_type in (
    'image',
    'audio',
    'video',
    'document'
  ) then
    media :=
      coalesce(
        new.metadata -> 'media',
        '{}'::jsonb
      );

    new.external_media_id :=
      coalesce(
        nullif(
          pg_catalog.btrim(
            new.external_media_id
          ),
          ''
        ),
        nullif(
          pg_catalog.btrim(
            media ->> 'id'
          ),
          ''
        )
      );

    new.mime_type :=
      coalesce(
        nullif(
          pg_catalog.btrim(
            new.mime_type
          ),
          ''
        ),
        nullif(
          pg_catalog.btrim(
            media ->> 'mime_type'
          ),
          ''
        )
      );

    new.file_name :=
      coalesce(
        nullif(
          pg_catalog.btrim(
            new.file_name
          ),
          ''
        ),
        nullif(
          pg_catalog.btrim(
            media ->> 'file_name'
          ),
          ''
        )
      );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_conversation_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  lead_contact_id uuid;
begin
  actor_id := (select auth.uid());

  if new.subject is not null then
    new.subject := nullif(
      pg_catalog.btrim(new.subject),
      ''
    );
  end if;


  -- Quando houver lead, o contato precisa ser o mesmo.

  if new.lead_id is not null then

    select lead.contact_id
    into lead_contact_id
    from public.leads as lead
    where lead.id = new.lead_id
      and lead.organization_id =
          new.organization_id;

    if not found then
      raise exception
        'O lead informado não pertence à empresa.';
    end if;

    if new.contact_id <> lead_contact_id then
      raise exception
        'O contato da conversa não corresponde ao contato do lead.';
    end if;

  end if;


  -- O responsável precisa estar ativo na empresa.

  if new.assigned_to is not null
     and not exists (
       select 1
       from public.organization_members as member
       where member.organization_id =
             new.organization_id
         and member.user_id =
             new.assigned_to
         and member.status = 'active'
     ) then

    raise exception
      'O responsável pela conversa não está ativo na empresa.';

  end if;


  if tg_op = 'INSERT' then

    new.created_by := coalesce(
      actor_id,
      new.created_by
    );

    new.updated_by := coalesce(
      actor_id,
      new.updated_by,
      new.created_by
    );

  else

    new.organization_id :=
      old.organization_id;

    new.created_by :=
      old.created_by;

    new.updated_by := coalesce(
      actor_id,
      old.updated_by
    );

  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_custom_field_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
begin
  actor_id := (select auth.uid());

  new.name := pg_catalog.btrim(new.name);
  new.code := pg_catalog.lower(
    pg_catalog.btrim(new.code)
  );

  if tg_op = 'INSERT' then

    new.created_by := coalesce(
      actor_id,
      new.created_by
    );

  else

    new.organization_id :=
      old.organization_id;

    new.code :=
      old.code;

    new.created_by :=
      old.created_by;

  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_lead_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  stage_category text;
  stage_requires_value boolean;
  stage_requires_loss_reason boolean;
  contact_name text;
begin
  select
    stage.category,
    stage.requires_value,
    stage.requires_loss_reason
  into
    stage_category,
    stage_requires_value,
    stage_requires_loss_reason
  from public.pipeline_stages as stage
  where stage.id = new.stage_id
    and stage.pipeline_id = new.pipeline_id
    and stage.organization_id = new.organization_id
    and stage.is_active = true;

  if not found then
    raise exception
      'A etapa informada não pertence ao funil ou está inativa.';
  end if;

  if new.title is null
     or pg_catalog.btrim(new.title) = '' then

    select contact.full_name
    into contact_name
    from public.contacts as contact
    where contact.id = new.contact_id
      and contact.organization_id = new.organization_id;

    new.title := contact_name;
  end if;

  if stage_category = 'won' then
    if stage_requires_value
       and coalesce(new.estimated_value, 0) <= 0 then
      raise exception
        'Informe o valor da oportunidade antes de concluir como ganha.';
    end if;

    new.status := 'won';
    new.closed_at := coalesce(new.closed_at, now());
    new.lost_reason := null;

  elsif stage_category = 'lost' then
    if stage_requires_loss_reason
       and nullif(
         pg_catalog.btrim(new.lost_reason),
         ''
       ) is null then

      raise exception
        'Informe o motivo da perda antes de concluir como perdida.';
    end if;

    new.status := 'lost';
    new.closed_at := coalesce(new.closed_at, now());

  else
    new.status := 'open';
    new.closed_at := null;
    new.lost_reason := null;
  end if;

  if tg_op = 'INSERT' then
    new.created_by := coalesce(
      new.created_by,
      (select auth.uid())
    );

    new.updated_by := coalesce(
      new.updated_by,
      new.created_by,
      (select auth.uid())
    );

    new.last_activity_at := coalesce(
      new.last_activity_at,
      now()
    );

  else
    new.updated_by := coalesce(
      new.updated_by,
      (select auth.uid()),
      old.updated_by
    );

    if new.stage_id is distinct from old.stage_id
       or new.pipeline_id is distinct from old.pipeline_id
       or new.assigned_to is distinct from old.assigned_to then

      new.last_activity_at := now();
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_message_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
  sender_name text;
  sender_role text;
begin
  actor_id := (select auth.uid());


  if not exists (
    select 1
    from public.conversations as conversation
    where conversation.id =
          new.conversation_id
      and conversation.organization_id =
          new.organization_id
  ) then

    raise exception
      'A conversa informada não pertence à empresa.';

  end if;


  if new.reply_to_message_id is not null
     and not exists (
       select 1
       from public.messages as replied_message
       where replied_message.id =
             new.reply_to_message_id
         and replied_message.organization_id =
             new.organization_id
         and replied_message.conversation_id =
             new.conversation_id
     ) then

    raise exception
      'A mensagem respondida pertence a outra conversa.';

  end if;


  if new.message_type in (
    'text',
    'template',
    'internal_note',
    'system'
  )
  and nullif(
    pg_catalog.btrim(new.body),
    ''
  ) is null then

    raise exception
      'Informe o conteúdo da mensagem.';

  end if;


  if new.message_type in (
    'image',
    'audio',
    'video',
    'document'
  )
  and new.external_media_id is null
  and new.media_storage_path is null then

    raise exception
      'Informe a mídia vinculada à mensagem.';

  end if;


  if new.direction = 'inbound' then

    new.sender_user_id := null;
    new.sender_name_snapshot := null;
    new.sender_role_snapshot := null;
    new.status := 'received';


  elsif new.direction = 'internal'
        and new.message_type = 'system'
        and actor_id is null
        and new.sender_user_id is null then

    new.sender_name_snapshot :=
      coalesce(
        new.sender_name_snapshot,
        'Sistema'
      );

    new.sender_role_snapshot :=
      coalesce(
        new.sender_role_snapshot,
        'Automação'
      );

    new.status := 'sent';


  else

    new.sender_user_id := coalesce(
      actor_id,
      new.sender_user_id
    );


    if new.sender_user_id is null then

      raise exception
        'Informe o usuário responsável pela mensagem.';

    end if;


    select
      profile.full_name,
      role.name
    into
      sender_name,
      sender_role
    from public.organization_members as member

    join public.profiles as profile
      on profile.id = member.user_id

    join public.roles as role
      on role.id = member.role_id

    where member.organization_id =
          new.organization_id
      and member.user_id =
          new.sender_user_id
      and member.status = 'active';


    if not found then

      raise exception
        'O remetente não está ativo na empresa.';

    end if;


    new.sender_name_snapshot :=
      coalesce(
        new.sender_name_snapshot,
        sender_name
      );

    new.sender_role_snapshot :=
      coalesce(
        new.sender_role_snapshot,
        sender_role
      );


    if new.direction = 'internal' then
      new.status := 'sent';
    end if;

  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_tag_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_id uuid;
